 CobraNavigationUiTest f;InfinityLiveActivity a;CobraSportsPreferences prefs;
 @Before public void setup()throws Exception{f=new CobraNavigationUiTest();f.clock();a=f.fixture(8);prefs=new CobraSportsPreferences(a);put(a,"mPrefs",prefs.prefs);prefs.prefs.edit().clear().putString("cobra_appearance_mode","dark").commit();put(a,"mCobraSportsLastRefresh",System.currentTimeMillis());put(a,"mCobraEffects",new CobraPresentationEffects(a));}
