 int pixel(Drawable d){d.setBounds(0,0,100,80);Bitmap b=Bitmap.createBitmap(100,80,Bitmap.Config.ARGB_8888);d.draw(new Canvas(b));int c=b.getPixel(50,40);b.recycle();return c;}
 String text(View v){String s=v instanceof TextView?((TextView)v).getText().toString():"";if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)s+="\n"+text(((ViewGroup)v).getChildAt(i));return s;}
 @Test public void oledOffIsBlackInEveryViewAndKeepsAccents()throws Exception{for(String mode:new String[]{"mobile","compact","cards","grid","focus"}){put(a,"mCobraGuideStyle",mode);assertEquals(Color.BLACK,call(a,"cobraModeColor","panel"));assertEquals(Color.BLACK,call(a,"cobraModeColor","background"));assertNotEquals(Color.BLACK,call(a,"cobraModeColor","accent"));assertEquals(Color.BLACK,pixel((Drawable)call(a,"cobraPhoneGlass",false,12,true)));}pro();CobraProUi.Action action=new CobraProUi.Action(a,"play","Play",false,false,()->{});action.measure(View.MeasureSpec.makeMeasureSpec(120,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(60,View.MeasureSpec.EXACTLY));action.layout(0,0,120,60);Bitmap b=Bitmap.createBitmap(120,60,Bitmap.Config.ARGB_8888);action.draw(new Canvas(b));assertEquals(Color.BLACK,b.getPixel(20,15));b.recycle();}
 @Test public void subtleAndImmersiveUseSeparatePoliciesWithoutVideoChanges()throws Exception{pro();Object texture=get(a,"mCobraPreviewTexture");prefs.prefs.edit().putString(CobraPresentationEffects.AMBIENT,"subtle").commit();CobraProUi.Hero hero=(CobraProUi.Hero)get(a,"mCobraProHeroUi");call(a,"cobraRefreshAmbient");assertEquals(CobraPresentationEffects.SUBTLE,call(a,"cobraProMaterialMode"));assertTrue(hero.transport.getBackground() instanceof CobraVisualRenderer.Glass);assertEquals(CobraPresentationEffects.SUBTLE,((CobraVisualRenderer.Glass)hero.transport.getBackground()).effectMode);assertNotEquals(Color.BLACK,pixel(hero.transport.getBackground()));prefs.prefs.edit().putString(CobraPresentationEffects.AMBIENT,"immersive").commit();assertEquals(CobraPresentationEffects.IMMERSIVE,CobraPresentationEffects.ambientMode(prefs.prefs));assertSame(texture,get(a,"mCobraPreviewTexture"));prefs.prefs.edit().putBoolean(CobraPresentationEffects.NIGHT,true).commit();put(a,"mPlayerOverlay",new FrameLayout(a));assertTrue((Boolean)call(a,"cobraProCinema"));assertEquals(CobraPresentationEffects.OFF,call(a,"cobraProMaterialMode"));assertFalse((Boolean)call(a,"cobraProOled"));}
 @Test public void onlyMobileLosesHeaderViewsAndKeepsBottomViews()throws Exception{for(String mode:new String[]{"mobile","compact","cards","grid","focus"}){put(a,"mCobraGuideStyle",mode);call(a,"cobraShowGuideShell");f.measure(a,412,915);View toolbar=(View)get(a,"mCobraModeToolbar");assertEquals(mode.equals("mobile"),f.description(toolbar,"Choose one of five view modes")==null);if(mode.equals("mobile")){assertNotNull(f.description((View)get(a,"mCobraModeFooter"),"Views"));assertNotNull(toolbar.findViewWithTag("cobra_mode_visuals"));}}}
