 @Test public void quickPeekIsAboveChannelsDrawerAndKeepsPreviewMute()throws Exception{pro();FrameLayout overlay=new FrameLayout(a);a.addContentView(overlay,new ViewGroup.LayoutParams(-1,-1));put(a,"mPlayerOverlay",overlay);FrameLayout drawer=new FrameLayout(a);drawer.setElevation(12);overlay.addView(drawer);put(a,"mCobraPlayerDrawer",drawer);call(a,"cobraShowQuickPeek",((List<?>)get(a,"mChannels")).get(1),drawer);View sheet=(View)get(a,"mCobraActionSheet");assertTrue(sheet.getElevation()>drawer.getElevation());assertSame(overlay,sheet.getParent());assertNotNull(sheet.findViewWithTag("cobra_quick_peek_video"));assertNotNull(sheet.findViewWithTag("cobra_quick_peek_state"));assertSame(drawer,get(a,"mCobraPlayerDrawer"));assertNull(get(a,"mPlayer"));}
 @Test public void fullscreenMultiPickerSportsListsActualLiveGamesOnly()throws Exception{pro();Object live=SportsHubTest.game();put(live,"state","in");Object upcoming=SportsHubTest.game();put(upcoming,"id","upcoming");put(upcoming,"state","pre");((List)get(a,"mCobraSportsGames")).add(live);((List)get(a,"mCobraSportsGames")).add(upcoming);FrameLayout overlay=new FrameLayout(a);a.addContentView(overlay,new ViewGroup.LayoutParams(-1,-1));put(a,"mPlayerOverlay",overlay);call(a,"showCobraMultiPicker",false);View picker=(View)get(a,"mCobraMultiPicker");assertNotNull(f.description(picker,"Sports"));call(a,"renderCobraMultiPicker","SPORTS");ListView list=(ListView)picker.findViewWithTag("cobra_multi_picker_list");assertEquals(1,list.getCount());assertSame(live,list.getAdapter().getItem(0));assertNull(get(a,"mPlayer"));}
 JSONObject schedule()throws Exception{JSONObject root=new JSONObject().put("season",new JSONObject().put("year",2026));JSONObject team=new JSONObject().put("id","8").put("displayName","Detroit Lions").put("abbreviation","DET").put("logo","").put("recordSummary","2-2").put("standingSummary","NFC North");root.put("team",team);JSONArray games=new JSONArray();for(int i:new int[]{1,3}){JSONObject cp=new JSONObject().put("team",team).put("homeAway","home").put("score",new JSONObject().put("displayValue","31"));JSONObject opp=new JSONObject().put("team",new JSONObject().put("id","18").put("displayName","Saints").put("abbreviation","NO")).put("homeAway","away").put("score",new JSONObject().put("displayValue","30"));JSONObject c=new JSONObject().put("status",new JSONObject().put("type",new JSONObject().put("state","post").put("completed",true))).put("competitors",new JSONArray().put(cp).put(opp)).put("broadcasts",new JSONArray().put(new JSONObject().put("media",new JSONObject().put("shortName","FOX"))));games.put(new JSONObject().put("id","game"+i).put("date",i==1?"2026-09-13T17:00Z":"2026-09-27T17:00Z").put("week",new JSONObject().put("number",i)).put("competitions",new JSONArray().put(c)));}return root.put("events",games);}
 @Test public void scheduleNormalizesScoresLogosNetworksAndKeepsByeWeeks()throws Exception{Object spec=call(a,"cobraSportsSpec","nfl"),team=SportsHubTest.team("8","nfl|8","Lions","DET","");JSONObject raw=schedule();Object season=call(a,"cobraParseTeamSeason",spec,team,raw,System.currentTimeMillis());List<?> weeks=(List<?>)get(season,"weeks");assertEquals(3,weeks.size());assertEquals(0,((List<?>)get(weeks.get(1),"games")).size());Object game=((List<?>)get(weeks.get(0),"games")).get(0);assertEquals("31",get(get(game,"home"),"score"));assertEquals("post",get(game,"state"));assertEquals(Arrays.asList("FOX"),get(game,"broadcasts"));assertTrue(raw.getJSONArray("events").getJSONObject(0).getJSONArray("competitions").getJSONObject(0).getJSONArray("competitors").getJSONObject(0).get("score") instanceof JSONObject);}
 @Test public void teamWeeksFilterGamesAndRespectSpoilersInsideProShell()throws Exception{pro();Object team=SportsHubTest.team("8","nfl|8","Detroit Lions","DET","");put(team,"leagueKey","nfl");((Map)get(a,"mCobraProTeamDirectory")).put("nfl",new ArrayList(Arrays.asList(team)));Object season=call(a,"cobraParseTeamSeason",call(a,"cobraSportsSpec","nfl"),team,schedule(),System.currentTimeMillis());((Map)get(a,"mCobraProTeamSeasons")).put("nfl|8",season);Object video=get(a,"mCobraPreviewTexture");call(a,"cobraProFilter",4);call(a,"cobraProSportsTab",4);call(a,"cobraProOpenTeam",team);put(a,"mCobraProTeamWeek",1);call(a,"cobraRenderGuideBrowser");f.measure(a,412,915);View browser=(View)get(a,"mCobraGuideBrowser");assertNotNull(browser.findViewWithTag("pro_team_game_game1"));assertNull(browser.findViewWithTag("pro_team_game_game3"));assertSame(video,get(a,"mCobraPreviewTexture"));prefs.protection(true);call(a,"cobraRenderGuideBrowser");assertFalse(text((View)get(a,"mCobraGuideBrowser")).contains("31"));assertFalse(text((View)get(a,"mCobraGuideBrowser")).contains("2-2"));prefs.protection(false);put(a,"mCobraProTeamWeek",2);call(a,"cobraRenderGuideBrowser");assertTrue(text((View)get(a,"mCobraGuideBrowser")).contains("No games scheduled this week"));f.image(a,"pro-team-details-317");}
